//! Runtime functions called from compiled code (System V convention).
//!
//! Functions that may unwind or run Lisp code are called through a `tail`
//! convention trampoline generated by kiln-cg; they receive the trampoline's
//! frame pointer as an extra last argument.

use crate::context::Context;
use crate::object::write_object;
use std::io::Write;

pub const ERR_NOT_FIXNUM: u64 = 1;
pub const ERR_OVERFLOW: u64 = 2;
pub const ERR_WRONG_NARGS: u64 = 3;
pub const ERR_NOT_LIST: u64 = 4;
pub const ERR_NOT_FUNCTION: u64 = 5;
pub const ERR_UNDEFINED_FUNCTION: u64 = 6;
pub const ERR_UNBOUND_VARIABLE: u64 = 7;
pub const ERR_NOT_SYMBOL: u64 = 8;
pub const ERR_ODD_KEYWORDS: u64 = 9;
pub const ERR_UNKNOWN_KEYWORD: u64 = 10;
pub const ERR_NOT_CHARACTER: u64 = 11;
pub const ERR_NOT_STRING: u64 = 12;
pub const ERR_NOT_VECTOR: u64 = 13;
pub const ERR_INDEX: u64 = 14;
pub const ERR_NOT_SEQUENCE: u64 = 15;
pub const ERR_NOT_INTEGER: u64 = 16;
pub const ERR_DIVISION_BY_ZERO: u64 = 17;
pub const ERR_NOT_NUMBER: u64 = 18;
pub const ERR_BAD_TYPE: u64 = 19;
/// ERROR before the condition system: OBJ is the list (DATUM . ARGUMENTS).
pub const ERR_LISP_ERROR: u64 = 20;
pub const ERR_UNDEFINED_SETF_FUNCTION: u64 = 21;

pub fn error_exit(msg: &str) -> ! {
    let _ = std::io::stdout().flush();
    eprintln!("kiln: error: {msg}");
    std::process::exit(1)
}

/// Debug printer: writes the object and a newline, returns the object.
///
/// # Safety
/// `obj` must be a valid Lisp value.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn kiln_rt_print(_ctx: *mut Context, obj: u64) -> u64 {
    let mut s = String::new();
    unsafe { write_object(&mut s, obj) };
    s.push('\n');
    let mut out = std::io::stdout().lock();
    let _ = out.write_all(s.as_bytes());
    obj
}

/// Signals an error. In M0 there is no condition system yet, so this prints
/// a message and exits. It is declared as unwinding so that call sites are
/// already compiled the way they will be once it signals a condition.
///
/// # Safety
/// `obj` must be a valid Lisp value.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn kiln_rt_error(ctx: *mut Context, code: u64, obj: u64, _fp: usize) -> ! {
    unsafe { error_with(ctx, code, obj) }
}

/// Signals the error `code` about `obj` (for now: reports it and exits).
///
/// # Safety
/// `obj` must be a valid Lisp value.
pub unsafe fn error_with(_ctx: *mut Context, code: u64, obj: u64) -> ! {
    let mut s = String::new();
    unsafe { write_object(&mut s, obj) };
    let msg = match code {
        ERR_NOT_FIXNUM => format!("the value {s} is not of type FIXNUM"),
        ERR_OVERFLOW => format!("fixnum overflow (bignums are not implemented yet), operand {s}"),
        ERR_WRONG_NARGS => format!("invalid number of arguments: {}", obj >> 1),
        ERR_NOT_LIST => format!("the value {s} is not of type LIST"),
        ERR_NOT_FUNCTION => format!("the value {s} is not of type FUNCTION"),
        ERR_UNDEFINED_FUNCTION => format!("the function {s} is undefined"),
        ERR_UNBOUND_VARIABLE => format!("the variable {s} is unbound"),
        ERR_NOT_SYMBOL => format!("the value {s} is not of type SYMBOL"),
        ERR_ODD_KEYWORDS => format!("odd number of keyword arguments: {s}"),
        ERR_UNKNOWN_KEYWORD => format!("unknown keyword argument {s}"),
        ERR_NOT_CHARACTER => format!("the value {s} is not of type CHARACTER"),
        ERR_NOT_STRING => format!("the value {s} is not of type STRING"),
        ERR_NOT_VECTOR => format!("the value {s} is not of type SIMPLE-VECTOR"),
        ERR_INDEX => format!("index {s} is out of bounds"),
        ERR_NOT_SEQUENCE => format!("the value {s} is not of type SEQUENCE"),
        ERR_NOT_INTEGER => format!("the value {s} is not of type INTEGER"),
        ERR_DIVISION_BY_ZERO => format!("division of {s} by zero"),
        ERR_NOT_NUMBER => format!("the value {s} is not of type REAL"),
        ERR_BAD_TYPE => format!("{s} is not a known type specifier"),
        ERR_LISP_ERROR => format!("error: {s}"),
        ERR_UNDEFINED_SETF_FUNCTION => format!("the function (SETF {s}) is undefined"),
        _ => format!("error code {code}, object {s}"),
    };
    error_exit(&msg)
}

/// Slow path of a poll point (C4). `entry` is the function that
/// `kiln_poll_retry` will re-enter, or 0 for an in-function poll.
///
/// # Safety
/// `ctx` must be valid.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn kiln_rt_poll(ctx: *mut Context, entry: usize, fp: usize) -> u64 {
    unsafe {
        (*ctx).poll_flag = 0;
        (*ctx).stack_limit = (*ctx).stack_real_limit;
    }
    crate::profile::poll(ctx, entry, fp);
    // 1: the stack is exhausted; the caller signals it.
    unsafe { crate::stack::check_stack(&mut *ctx, fp) as u64 }
}

static NEXT_IDENTITY_HASH: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(1);

/// The identity hash counter, which an image saves (image.rs).
pub(crate) fn next_identity_hash() -> u64 {
    NEXT_IDENTITY_HASH.load(std::sync::atomic::Ordering::Relaxed)
}

pub(crate) fn set_next_identity_hash(n: u64) {
    NEXT_IDENTITY_HASH.store(n, std::sync::atomic::Ordering::Relaxed);
}

/// The identity hash of `obj` as a fixnum: stable across moving
/// collections. Heap objects get one on first request, stored in header
/// bits 40..64, as are static objects' (computed from their address);
/// immediates hash by their bits. Not a safepoint.
///
/// # Safety
/// `obj` must be a valid Lisp value.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn kiln_rt_identity_hash(_ctx: *mut Context, obj: u64) -> u64 {
    use crate::object::{HASH_SHIFT, is_cons, is_general, untag};
    // Objects of an image keep theirs in the header too: they were heap
    // objects when it was saved.
    let hash = if (is_cons(obj) || is_general(obj))
        && (crate::gc::in_mmtk_space(obj) || crate::image::contains(untag(obj)))
    {
        let header = untag(obj) as *mut u64;
        let h = unsafe { *header };
        let existing = h >> HASH_SHIFT;
        if existing != 0 {
            existing
        } else {
            // Spread consecutive numbers over the 24 bits (Fibonacci hashing).
            let n = NEXT_IDENTITY_HASH.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
            let mut new = (n.wrapping_mul(0x9e37_79b9_7f4a_7c15) >> 40) & 0xff_ffff;
            if new == 0 {
                new = 1;
            }
            unsafe { *header = (h & ((1u64 << HASH_SHIFT) - 1)) | (new << HASH_SHIFT) };
            new
        }
    } else if is_cons(obj) || is_general(obj) {
        // Static objects (module data, NIL and T, which are writable and
        // never move): a hash from the address, kept in the header like a
        // heap object's, so that the inline path of compiled code finds it
        // next time (slot names and other constant symbols are hashed
        // often).
        let header = untag(obj) as *mut u64;
        let h = unsafe { *header };
        let existing = h >> HASH_SHIFT;
        if existing != 0 {
            existing
        } else {
            let mut new = (obj.wrapping_mul(0x9e37_79b9_7f4a_7c15) >> 40) & 0xff_ffff;
            if new == 0 {
                new = 1;
            }
            unsafe { *header = (h & ((1u64 << HASH_SHIFT) - 1)) | (new << HASH_SHIFT) };
            new
        }
    } else {
        // Immediates: mix the bits.
        (obj.wrapping_mul(0x9e37_79b9_7f4a_7c15) >> 24) & ((1u64 << 40) - 1)
    };
    hash << 1
}

/// Writes the octets `vec[start..end]` to the file descriptor `fd`: `vec`
/// is a simple vector of fixnums (the contents of an `(unsigned-byte 8)`
/// vector). Returns the number of octets written (a fixnum),
/// or -1 on error.
///
/// # Safety
/// `vec` must be a simple vector of fixnums with `start <= end <= length`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn kiln_rt_fd_write(
    _ctx: *mut Context,
    fd: u64,
    vec: u64,
    start: u64,
    end: u64,
) -> u64 {
    use crate::object::{fixnum_value, untag};
    let (start, end) = (fixnum_value(start) as usize, fixnum_value(end) as usize);
    let elements = (untag(vec) + 8) as *const u64;
    let bytes: Vec<u8> = (start..end)
        .map(|i| fixnum_value(unsafe { *elements.add(i) }) as u8)
        .collect();
    let mut written = 0;
    while written < bytes.len() {
        let n = unsafe {
            libc::write(
                fixnum_value(fd) as libc::c_int,
                bytes[written..].as_ptr() as *const libc::c_void,
                bytes.len() - written,
            )
        };
        if n < 0 {
            if std::io::Error::last_os_error().kind() == std::io::ErrorKind::Interrupted {
                continue;
            }
            return (-1i64 as u64) << 1;
        }
        written += n as usize;
    }
    (written as u64) << 1
}

/// Reads at most `end - start` octets from `fd` into `vec[start..]` (a
/// simple vector, elements stored as fixnums). Returns the number read (0
/// at end of file), or -1 on error.
///
/// # Safety
/// As `kiln_rt_fd_write`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn kiln_rt_fd_read(
    _ctx: *mut Context,
    fd: u64,
    vec: u64,
    start: u64,
    end: u64,
) -> u64 {
    use crate::object::{fixnum_value, untag};
    let (start, end) = (fixnum_value(start) as usize, fixnum_value(end) as usize);
    let mut buffer = vec![0u8; end.saturating_sub(start)];
    let n = loop {
        let n = unsafe {
            libc::read(
                fixnum_value(fd) as libc::c_int,
                buffer.as_mut_ptr() as *mut libc::c_void,
                buffer.len(),
            )
        };
        if n < 0 && std::io::Error::last_os_error().kind() == std::io::ErrorKind::Interrupted {
            continue;
        }
        break n;
    };
    if n < 0 {
        return (-1i64 as u64) << 1;
    }
    let elements = (untag(vec) + 8) as *mut u64;
    for (i, b) in buffer[..n as usize].iter().enumerate() {
        unsafe { *elements.add(start + i) = (*b as u64) << 1 };
    }
    (n as u64) << 1
}

/// The octets of `vec`, a simple vector of fixnums (an encoded file name).
///
/// # Safety
/// `vec` must be a simple vector of fixnums.
pub(crate) unsafe fn vector_octets(vec: u64) -> Vec<u8> {
    use crate::object::{fixnum_value, header, header_length, untag};
    let n = header_length(unsafe { header(vec) });
    let elements = (untag(vec) + 8) as *const u64;
    (0..n).map(|i| fixnum_value(unsafe { *elements.add(i) }) as u8).collect()
}

/// Stores `bytes` into the simple vector `vec` as fixnums if they fit;
/// returns their count either way (the caller retries with a longer vector
/// if it is greater than the length of `vec`).
///
/// # Safety
/// `vec` must be a simple vector.
unsafe fn store_octets(vec: u64, bytes: &[u8]) -> i64 {
    use crate::object::{header, header_length, untag};
    let n = header_length(unsafe { header(vec) });
    if bytes.len() > n {
        return bytes.len() as i64;
    }
    let elements = (untag(vec) + 8) as *mut u64;
    for (i, b) in bytes.iter().enumerate() {
        unsafe { *elements.add(i) = (*b as u64) << 1 };
    }
    bytes.len() as i64
}

/// The file name in the octet vector `vec`.
fn os_name(vec: u64) -> std::ffi::OsString {
    use std::os::unix::ffi::OsStringExt;
    std::ffi::OsString::from_vec(unsafe { vector_octets(vec) })
}

fn c_path(bytes: Vec<u8>) -> Option<std::ffi::CString> {
    std::ffi::CString::new(bytes).ok()
}

/// File system calls for pathnames and file streams. `op`
/// selects the call; file names are simple vectors of octets (UTF-8), and
/// results that are names are stored into the simple vector given as the
/// last argument (the result is then their length; if that is greater
/// than the length of the vector, nothing was stored). Other results are
/// fixnums; a failure is minus errno. All arguments and results are
/// tagged.
///
/// - 0 open(name, flags, mode): flags 1 read, 2 write, 4 create, 8
///   truncate, 16 append, 32 exclusive. The descriptor.
/// - 1 close(fd).
/// - 2 lseek(fd, offset, whence): whence 0 start, 1 current, 2 end.
/// - 3 unlink(name). 4 rename(name, new-name). 5 mkdir(name, mode).
///   6 rmdir(name).
/// - 7 stat(name, which): which 0: kind (0 none, 1 file, 2 directory, 3
///   other); 1: size; 2: modification time (seconds since 1970).
/// - 8 getcwd(buffer). 9 realpath(name, buffer). 10 getenv(name, buffer):
///   -1 if unset.
/// - 11 the entries of directory `name` (without . and ..), each followed
///   by a 0 octet, into buffer.
/// - 12 the size of the open file fd.
/// - 13 strerror(errno, buffer).
/// - 14 the monotonic clock in microseconds. 15 the time in seconds since
///   1970. 16 the processor time of the process in microseconds.
/// - 17 sleep for a microseconds. 18 exit with status a.
///
/// # Safety
/// The arguments must be as described.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn kiln_rt_sys(_ctx: *mut Context, op: u64, a: u64, b: u64, c: u64) -> u64 {
    use crate::object::fixnum_value;
    let fixnum = |n: i64| (n << 1) as u64;
    let errno = || -(std::io::Error::last_os_error().raw_os_error().unwrap_or(1) as i64);
    let check = |r: i64| if r < 0 { errno() } else { r };
    let name = |v: u64| c_path(unsafe { vector_octets(v) });
    let einval = -(libc::EINVAL as i64);
    let result: i64 = match fixnum_value(op) {
        0 => match name(a) {
            None => einval,
            Some(path) => {
                let flags = fixnum_value(b);
                let mut f = match flags & 3 {
                    1 => libc::O_RDONLY,
                    2 => libc::O_WRONLY,
                    _ => libc::O_RDWR,
                } | libc::O_CLOEXEC;
                if flags & 4 != 0 {
                    f |= libc::O_CREAT;
                }
                if flags & 8 != 0 {
                    f |= libc::O_TRUNC;
                }
                if flags & 16 != 0 {
                    f |= libc::O_APPEND;
                }
                if flags & 32 != 0 {
                    f |= libc::O_EXCL;
                }
                let mode = fixnum_value(c) as libc::c_uint;
                check(unsafe { libc::open(path.as_ptr(), f, mode) } as i64)
            }
        },
        1 => check(unsafe { libc::close(fixnum_value(a) as libc::c_int) } as i64),
        2 => {
            let whence = match fixnum_value(c) {
                0 => libc::SEEK_SET,
                1 => libc::SEEK_CUR,
                _ => libc::SEEK_END,
            };
            check(unsafe { libc::lseek(fixnum_value(a) as libc::c_int, fixnum_value(b), whence) })
        }
        3 => match name(a) {
            None => einval,
            Some(path) => check(unsafe { libc::unlink(path.as_ptr()) } as i64),
        },
        4 => match (name(a), name(b)) {
            (Some(from), Some(to)) => check(unsafe { libc::rename(from.as_ptr(), to.as_ptr()) } as i64),
            _ => einval,
        },
        5 => match name(a) {
            None => einval,
            Some(path) => {
                check(unsafe { libc::mkdir(path.as_ptr(), fixnum_value(b) as libc::mode_t) } as i64)
            }
        },
        6 => match name(a) {
            None => einval,
            Some(path) => check(unsafe { libc::rmdir(path.as_ptr()) } as i64),
        },
        7 => match name(a) {
            None => einval,
            Some(path) => {
                let mut st: libc::stat = unsafe { std::mem::zeroed() };
                if unsafe { libc::stat(path.as_ptr(), &mut st) } < 0 {
                    if fixnum_value(b) == 0 { 0 } else { errno() }
                } else {
                    match fixnum_value(b) {
                        0 => match st.st_mode & libc::S_IFMT {
                            libc::S_IFREG => 1,
                            libc::S_IFDIR => 2,
                            _ => 3,
                        },
                        1 => st.st_size,
                        _ => st.st_mtime,
                    }
                }
            }
        },
        8 => match std::env::current_dir() {
            Ok(dir) => unsafe { store_octets(a, dir.as_os_str().as_encoded_bytes()) },
            Err(e) => -(e.raw_os_error().unwrap_or(1) as i64),
        },
        9 => match std::fs::canonicalize(os_name(a)) {
            Ok(path) => unsafe { store_octets(b, path.as_os_str().as_encoded_bytes()) },
            Err(e) => -(e.raw_os_error().unwrap_or(1) as i64),
        },
        10 => match std::env::var_os(os_name(a)) {
            Some(value) => unsafe { store_octets(b, value.as_encoded_bytes()) },
            None => -1,
        },
        11 => match std::fs::read_dir(os_name(a)) {
            Ok(entries) => {
                let mut bytes = Vec::new();
                for entry in entries.flatten() {
                    bytes.extend_from_slice(entry.file_name().as_encoded_bytes());
                    bytes.push(0);
                }
                unsafe { store_octets(b, &bytes) }
            }
            Err(e) => -(e.raw_os_error().unwrap_or(1) as i64),
        },
        12 => {
            let mut st: libc::stat = unsafe { std::mem::zeroed() };
            if unsafe { libc::fstat(fixnum_value(a) as libc::c_int, &mut st) } < 0 {
                errno()
            } else {
                st.st_size
            }
        }
        13 => {
            let message = std::io::Error::from_raw_os_error(fixnum_value(a) as i32).to_string();
            unsafe { store_octets(b, message.as_bytes()) }
        }
        14 | 16 => {
            let clock = if fixnum_value(op) == 14 {
                libc::CLOCK_MONOTONIC
            } else {
                libc::CLOCK_PROCESS_CPUTIME_ID
            };
            let mut ts: libc::timespec = unsafe { std::mem::zeroed() };
            unsafe { libc::clock_gettime(clock, &mut ts) };
            ts.tv_sec * 1_000_000 + ts.tv_nsec / 1000
        }
        15 => match std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH) {
            Ok(d) => d.as_secs() as i64,
            Err(_) => 0,
        },
        17 => {
            std::thread::sleep(std::time::Duration::from_micros(fixnum_value(a).max(0) as u64));
            0
        }
        18 => {
            use std::io::Write;
            let _ = std::io::stdout().flush();
            {
                crate::profile::finish_from_env();
                std::process::exit(fixnum_value(a) as i32)
            }
        }
        _ => einval,
    };
    fixnum(result)
}

/// The shortest decimal representation of the float `x` that reads back
/// as the same float (for the printer): `which` selects the
/// part. 0: the significand, a nonnegative integer without trailing zeros
/// (0 for zero); 1: the exponent `e` such that |x| = significand * 10^e
/// (or 10000 for an infinity, 10001 for a NaN); 2: the sign, 1 or -1 (-1
/// for -0.0). All three are fixnums.
///
/// # Safety
/// `x` must be a single-float or a double-float.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn kiln_rt_float_decimal(_ctx: *mut Context, x: u64, which: u64) -> u64 {
    use crate::number::{double_value, is_single, single_value};
    let (text, negative, special) = if is_single(x) {
        let f = single_value(x);
        (format!("{:e}", f.abs()), f.is_sign_negative(), f.is_infinite() as u8 + 2 * f.is_nan() as u8)
    } else {
        let f = unsafe { double_value(x) };
        (format!("{:e}", f.abs()), f.is_sign_negative(), f.is_infinite() as u8 + 2 * f.is_nan() as u8)
    };
    let fixnum = |n: i64| (n << 1) as u64;
    match fixnum_value(which) {
        2 => fixnum(if negative { -1 } else { 1 }),
        1 if special == 1 => fixnum(10000),
        1 if special >= 2 => fixnum(10001),
        _ if special != 0 => fixnum(0),
        part => {
            // "d.ddde[-]n": the digits and the exponent of the first digit.
            let (mantissa, exponent) = text.split_once('e').unwrap();
            let digits: String = mantissa.chars().filter(|c| *c != '.').collect();
            let exponent: i64 = exponent.parse().unwrap();
            let digits = digits.trim_end_matches('0');
            if digits.is_empty() {
                return fixnum(0);
            }
            if part == 0 {
                fixnum(digits.parse::<i64>().unwrap())
            } else {
                fixnum(exponent - (digits.len() as i64 - 1))
            }
        }
    }
}

use crate::object::fixnum_value;
